choose.when:
SELECT TO_CHAR(hc.updated_at + INTERVAL '8 hours',
'YYYY-MM-DD HH24:00' 'IYYY-IW' 'YYYY-MM-DD'
) AS "date", COUNT(*) AS "count", COALESCE(hc.agent_id, 'unknown_agent') AS "category" FROM amp_sessions hc WHERE hc.updated_at IS NOT NULL AND hc.updated_at >= #{startTime} GROUP BY 1, 3 ORDER BY 1

SELECT TO_CHAR(hm.created_at + INTERVAL '8 hours',
'YYYY-MM-DD HH24:00' 'IYYY-IW' 'YYYY-MM-DD'
) AS "date", SUM(COALESCE((hm.extra_metadata -> 'usage_metadata' ->> 'input_tokens')::BIGINT, 0)) AS "count", 'input_tokens' AS "category" FROM amp_messages hm INNER JOIN amp_sessions hc ON hc.id = hm.conversation_id WHERE hm.created_at >= #{startTime} AND hm.extra_metadata IS NOT NULL AND hm.extra_metadata -> 'usage_metadata' IS NOT NULL GROUP BY 1 UNION ALL SELECT TO_CHAR(hm.created_at + INTERVAL '8 hours',
'YYYY-MM-DD HH24:00' 'IYYY-IW' 'YYYY-MM-DD'
) AS "date", SUM(COALESCE((hm.extra_metadata -> 'usage_metadata' ->> 'output_tokens')::BIGINT, 0)) AS "count", 'output_tokens' AS "category" FROM amp_messages hm INNER JOIN amp_sessions hc ON hc.id = hm.conversation_id WHERE hm.created_at >= #{startTime} AND hm.extra_metadata IS NOT NULL AND hm.extra_metadata -> 'usage_metadata' IS NOT NULL GROUP BY 1 ORDER BY 1

SELECT TO_CHAR(htc.created_at + INTERVAL '8 hours',
'YYYY-MM-DD HH24:00' 'IYYY-IW' 'YYYY-MM-DD'
) AS "date", COUNT(*) AS "count", COALESCE(htc.tool_name, 'unknown_tool') AS "category" FROM amp_tool_calls htc INNER JOIN amp_messages hm ON hm.id = htc.message_id INNER JOIN amp_sessions hc ON hc.id = hm.conversation_id WHERE htc.created_at >= #{startTime} GROUP BY 1, 3 ORDER BY 1

choose.otherwise:
SELECT TO_CHAR(hm.created_at + INTERVAL '8 hours',
'YYYY-MM-DD HH24:00' 'IYYY-IW' 'YYYY-MM-DD'
) AS "date", COUNT(*) AS "count", hm.extra_metadata -> 'response_metadata' ->> 'model_name' AS "category" FROM amp_messages hm INNER JOIN amp_sessions hc ON hc.id = hm.conversation_id WHERE hm.role = 'assistant' AND hm.created_at >= #{startTime} AND hm.extra_metadata IS NOT NULL GROUP BY 1, 3 ORDER BY 1

mapper.select:
SELECT COUNT(*)
FROM amp_tool_calls htc
INNER JOIN amp_messages hm ON hm.id = htc.message_id
INNER JOIN amp_sessions hc ON hc.id = hm.conversation_id


        AND htc.status = #{status}


        AND htc.created_at >= #{since}


        AND htc.created_at < #{until}

SELECT DISTINCT ON (slug) slug AS "agentId", name FROM amp_agents WHERE slug IN
#{slug}
ORDER BY slug, tenant_id NULLS FIRST

SELECT COUNT(*) FROM ( SELECT s.user_id FROM sessions s INNER JOIN users u ON u.id = s.user_id AND u.deleted_at IS NULL WHERE s.deleted_at IS NULL AND s.user_id IS NOT NULL AND s.user_id <> '' AND s.updated_at >= #{since}
AND s.updated_at < #{until}
UNION SELECT s.user_id FROM messages m INNER JOIN sessions s ON s.id = m.session_id INNER JOIN users u ON u.id = s.user_id AND u.deleted_at IS NULL WHERE m.deleted_at IS NULL AND s.deleted_at IS NULL AND s.user_id IS NOT NULL AND s.user_id <> '' AND m.created_at >= #{since}
AND m.created_at < #{until}
) active_users

SELECT s.score, u.id, u.username, u.email, u.avatar, u.tenant_id FROM (SELECT COUNT(user_id) score, user_id FROM sessions s WHERE s.deleted_at IS NULL AND s.user_id IS NOT NULL AND s.user_id <> '' AND s.updated_at >= #{since}
AND m.created_at < #{until}
GROUP BY user_id) s INNER JOIN users u ON u.deleted_at IS NULL AND u.id = s.user_id ORDER BY s.score DESC

SELECT id, title, agent_id, agent_name, updated_at
FROM
    (SELECT s.id, s.title, s.agent_config ->> 'agent_id' agent_id, a.name agent_name, s.updated_at
    FROM sessions s
    LEFT JOIN custom_agents a ON a.tenant_id = s.tenant_id AND a.id = s.agent_config ->> 'agent_id'
    WHERE s.deleted_at IS NULL
          AND s.agent_config ->> 'agent_id' IS NOT NULL
          AND s.updated_at >= #{since}

              AND s.updated_at < #{until}

    UNION
    SELECT hc.id::text, hc.title, hc.agent_id, ha.name agent_name, hc.updated_at
    FROM amp_sessions hc
    LEFT JOIN amp_agents ha ON ha.slug = hc.agent_id
    WHERE hc.status <> 'deleted'
          AND hc.updated_at >= #{since}

              AND hc.updated_at < #{until}

    )
ORDER BY updated_at DESC;
